}

#customerDetail {
	border-radius: 5px;
	background-color: #f2f2f2;
	padding-bottom: 20px;
}

.information {
	margin-left: 10px;
	margin-bottom: 3px;
}

.timelineContainer .timeline .subtitle {
	white-space: pre-wrap;
}

.timelineContainer .timeline .title {
	white-space: pre-wrap;
}

.timelineContainer .timeline .content {
	white-space: pre-wrap;
}

.mergedCustomerLine {
	margin-left: 30px;
	cursor: pointer;
}

.mergedCustomerLine:hover {
	cursor:pointer;
}

.action-link-display-more {
	color: #000000;
	text-decoration: underline;
	font-weight: bold;
	list-style: none;
}

.action-link {
	color: #008998;
	text-decoration: underline;
	cursor: pointer;
}

.action-divider {
	background-color: #008998 !important;
	margin-right: 10px !important;
	margin-left: 10px !important;
}

.backgroundButton {
